import type { ComponentProps } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every RHS UI field shares: Input, Textarea and the Select and
 * Combobox triggers. Quiet at rest, a ring on focus, a destructive border
 * when `aria-invalid` is set by your form library.
 */
export const fieldSurface = cn(
  "rounded-md border border-input bg-background text-sm text-foreground shadow-xs",
  "transition-[border-color,box-shadow] duration-150 outline-none",
  "focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/40",
  "aria-invalid:border-destructive aria-invalid:ring-destructive/25 aria-invalid:focus-visible:ring-destructive/30",
  "disabled:cursor-not-allowed disabled:opacity-50",
);

/** A text input on the field surface. Pair it with <Label htmlFor>. */
export function Input({ className, type = "text", ...props }: ComponentProps<"input">) {
  return (
    <input
      type={type}
      data-slot="input"
      className={cn(
        fieldSurface,
        "flex h-9 w-full min-w-0 px-3 py-1",
        "placeholder:text-muted-foreground selection:bg-primary selection:text-primary-foreground",
        "file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground",
        "disabled:pointer-events-none",
        className,
      )}
      {...props}
    />
  );
}
